From 9aca0b4824339b6d40be8c2162f98b90aa8b93a0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:50:45 +0100
Subject: [PATCH] applets/notes: add a Plasma Style background option

Sticky notes could only use their own colored papers or a fully
transparent background, so they never matched the other widgets. Add a
"Plasma Style" choice that uses the standard widget background instead.

BUG: 526480
---
 applets/notes/noteshelper.cpp          |  5 +++++
 applets/notes/qml/configAppearance.qml | 12 ++++++++++--
 applets/notes/qml/main.qml             |  5 +++--
 3 files changed, 18 insertions(+), 4 deletions(-)

diff --git a/applets/notes/noteshelper.cpp b/applets/notes/noteshelper.cpp
index 0c826dc51..b9ffe0942 100644
--- a/applets/notes/noteshelper.cpp
+++ b/applets/notes/noteshelper.cpp
@@ -13,6 +13,8 @@

 #include "noteiconengine.h"

+using namespace Qt::StringLiterals;
+
 NotesHelper::NotesHelper(QObject *parent)
     : QObject(parent)
 {
@@ -34,5 +36,8 @@ QString NotesHelper::fileContents(const QString &path) const

 QIcon NotesHelper::noteIcon(const QString &color) const
 {
+    if (color == "theme"_L1) {
+        return QIcon::fromTheme(u"preferences-desktop-plasma-theme"_s);
+    }
     return QIcon{new NoteIconEngine{color}};
 }
diff --git a/applets/notes/qml/configAppearance.qml b/applets/notes/qml/configAppearance.qml
index fe8537acd..12f938fba 100644
--- a/applets/notes/qml/configAppearance.qml
+++ b/applets/notes/qml/configAppearance.qml
@@ -47,6 +47,7 @@ KCM.GridViewKCM {
         if (!kcm.inPanel) {
             model.push("translucent-light");
         }
+        model.push("theme");
         return model;
     }
     view.currentIndex: {
@@ -79,6 +80,7 @@ KCM.GridViewKCM {
             case "pink": return i18nc("@item text on sticky note color option", "A pink sticky note")
             case "translucent": return i18nc("@item text on sticky note color option", "A transparent sticky note")
             case "translucent-light": return i18nc("@item text on sticky note color option", "A transparent sticky note with light text")
+            case "theme": return i18nc("@item text on sticky note color option", "A sticky note with the Plasma Style background")
             }
         }

@@ -89,9 +91,15 @@ KCM.GridViewKCM {
                 anchors.centerIn: parent
                 width: delegate.availableHeight
                 height: delegate.availableHeight
-                imagePath: "widgets/notes"
+                imagePath: delegate.modelData === "theme" ? "" : "widgets/notes"
                 elementId: delegate.modelData + "-notes"

+                KSvg.FrameSvgItem {
+                    anchors.fill: parent
+                    visible: delegate.modelData === "theme"
+                    imagePath: "widgets/background"
+                }
+
                 QQC2.Label {
                     id: thumbnailLabel
                     anchors.centerIn: parent
@@ -109,7 +117,7 @@ KCM.GridViewKCM {
                     //this is deliberately _NOT_ the theme color as we are over a known bright background
                     //an unknown colour over a known colour is a bad move as you end up with white on yellow
                     color: {
-                        if (kcm.inPanel && delegate.modelData === "translucent") {
+                        if ((kcm.inPanel && delegate.modelData === "translucent") || delegate.modelData === "theme") {
                             return Kirigami.Theme.textColor;
                         } else if (delegate.modelData === "black" || delegate.modelData === "translucent-light") {
                             return "#dfdfdf"
diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..828dee6de 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -32,7 +32,7 @@ PlasmoidItem {
     expandedOnDragHover: true

     Plasmoid.icon: "knotes-symbolic"
-    Plasmoid.backgroundHints: PlasmaCore.Types.NoBackground
+    Plasmoid.backgroundHints: Plasmoid.configuration.color === "theme" ? PlasmaCore.Types.DefaultBackground : PlasmaCore.Types.NoBackground

     // this isn't a frameSVG, the default SVG margins take up around 7% of the frame size, so we use that
     readonly property int horizontalMargins: Math.round(fullRepresentationItem.width * 0.07)
@@ -699,6 +699,7 @@ PlasmoidItem {
             if (!root.inPanel) {
                 model.push({text: i18nc("@item:inmenu", "Transparent Light"), color: "translucent-light"});
             }
+            model.push({text: i18nc("@item:inmenu", "Plasma Style"), color: "theme"});
             return model;
         }

@@ -728,6 +729,6 @@ PlasmoidItem {
         }

         // set imperatively to avoid binding loop during startup
-        root.noBackground = Qt.binding(() => inPanel && (Plasmoid.configuration.color === "translucent" || Plasmoid.configuration.color === "translucent-light"))
+        root.noBackground = Qt.binding(() => Plasmoid.configuration.color === "theme" || (inPanel && (Plasmoid.configuration.color === "translucent" || Plasmoid.configuration.color === "translucent-light")))
     }
 }
-- 
